function ColumnResizing({
  caption = "{{caption}}",
  accent = "{{accent}}",
  columnWidth = {{columnWidth}},
  resizerVisible = {{resizerVisible}},
  minWidthGuide = {{minWidthGuide}},
}) {
  const rows = [
    ["#1042", "A. Whitfield", "Shipped", "£64.00"],
    ["#1041", "R. Okafor", "Processing", "£128.50"],
    ["#1040", "M. Iqbal", "Shipped", "£22.00"],
    ["#1039", "S. Novak", "Refunded", "£40.00"],
  ];
  const cell = { padding: "10px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" };
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%", tableLayout: "fixed" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              <th scope="col" style={cell}>Order</th>
              <th scope="col" style={{ ...cell, width: columnWidth, position: "relative" }}>
                Customer
                {resizerVisible && <span aria-hidden="true" style={{ position: "absolute", top: 0, right: 0, bottom: 0, width: 8, cursor: "col-resize" }} />}
                {minWidthGuide && <span aria-hidden="true" style={{ position: "absolute", top: 0, bottom: -400, left: 100, borderLeft: "1px dashed #24143080", pointerEvents: "none" }} />}
              </th>
              <th scope="col" style={cell}>Status</th>
              <th scope="col" style={cell}>Total</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row[0]}>
                <td style={cell}>{row[0]}</td>
                <td style={{ ...cell, width: columnWidth }}>{row[1]}</td>
                <td style={cell}>{row[2]}</td>
                <td style={cell}>{row[3]}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
